<?php $product = $route['record']; $isLoader = $product['category'] === 'skid-steer-loaders'; $gallery = bl_product_gallery($product); $mainIndex = bl_product_main_index($product, $gallery) ?? 0; $keySpecs = bl_key_specs($product); $videos = bl_product_videos($product); $terms = bl_product_terms($product);
$copyPage = bl_product_family_key($product);
// This product's own lead time (or the site-wide one) fills {lead_time}, {lead_time_words} and {lead_unit} in the copy.
$leadVars = ["lead_time" => $terms["lead"]["value"], "lead_time_words" => str_replace(["–", "—"], " to ", (string) $terms["lead"]["value"]), "lead_unit" => $terms["lead"]["unit"]];
$copy = static fn(string $key, array $vars = []): string => bl_family_copy($copyPage, "product.copy." . $key, ["model" => $product["model"], "name" => $product["name"]] + $leadVars + $vars);
// The heading already carries the model, so the line under it is the rest of the name. The generated summary only repeats
// the name and the key figures shown below it, so the hero shows a summary only when one was written in WordPress.
$nameLine = trim(preg_replace('/^' . preg_quote($product['model'], '/') . '\s*/', '', $product['name'])) ?: $product['name'];
$customExcerpt = $product['excerpt'] !== bl_product_excerpt($product) ? $product['excerpt'] : '';
// Everything below the specification comes from data the site already keeps (inc/product-page.php); empty parts are left out.
$highlights = bl_product_highlights($product);
$drawings = bl_product_photos($product, ['drawing']);
$attachmentsShown = bl_product_attachments($product);
$dumperJobs = bl_product_dumper_jobs($product);
$applicationsShown = bl_product_applications($product);
$casesShown = bl_product_cases($product);
$photos = bl_product_photos($product, ['at-work', 'detail', 'factory', 'delivery']);
$factory = bl_product_factory($product);
$loading = bl_product_loading($product);
$faq = bl_product_faq($product);
$neighbours = bl_product_neighbours($product);
$compareRows = $neighbours ? bl_product_compare_rows($product, $neighbours) : [];
$hasOverview = !empty($product['content_html']) || $highlights || $videos;
$familyUrl = bl_url('/products/' . $product['category'] . '/');
$sections = array_filter([
    'overview' => $hasOverview ? $copy('nav_overview') : null,
    'specifications' => $product['specs'] ? $copy('nav_specifications') : $copy('nav_configuration'),
    'works-with' => $attachmentsShown || $dumperJobs ? $copy('nav_works') : null,
    'where-it-works' => $applicationsShown || $casesShown ? $copy('nav_applications') : null,
    'photos' => $photos ? $copy('nav_photos') : null,
    'built' => $factory ? $copy('nav_built') : null,
    'buying' => $copy('nav_buying'),
    'questions' => $faq ? $copy('nav_faq') : null,
]);
// One gallery for the lightbox: the photographs beside the main image, then the drawings and photographs further down.
$lightboxIndex = 0; ?>
<div class="bl-shell"><?php bl_breadcrumbs([['label' => bl_family_label($product['category']), 'url' => $familyUrl], ['label' => $product['model']]]); ?></div>
<section class="bl-product-hero bl-shell">
  <div class="bl-product-gallery"><?php if (count($gallery) > 1): ?><div class="bl-gallery-thumbs" aria-label="Product photographs"><?php foreach ($gallery as $i => $image): ?><button type="button" data-gallery-image="<?= bl_escape($image['src']) ?>" data-gallery-alt="<?= bl_escape($image['alt']) ?>" data-gallery-index="<?= $i ?>" aria-label="Show photograph <?= $i + 1 ?> of <?= count($gallery) ?>" aria-pressed="<?= $i === $mainIndex ? 'true' : 'false' ?>"><img src="<?= bl_escape($image['src']) ?>" alt="" width="120" height="120" loading="<?= $i < 5 ? 'eager' : 'lazy' ?>"></button><?php endforeach; ?></div><?php endif; ?><div class="bl-product-main-image"><?php if ($product['image']): ?><img id="product-photo" src="<?= bl_escape($product['image']) ?>" alt="<?= bl_escape($gallery[$mainIndex]['alt'] ?? $product['name']) ?>" width="1000" height="1000" fetchpriority="high"><button class="bl-gallery-zoom" type="button" data-lightbox-open="<?= $mainIndex ?>" hidden><?= bl_icon('magnifying-glass') ?><span>View larger<?= count($gallery) > 1 ? ' · ' . count($gallery) . ' photos' : '' ?></span></button><?php else: ?><span class="bl-product-image-empty">Contact our team for product photographs.</span><?php endif; ?></div>
    <?php if ($product['image']): ?><ul class="bl-lightbox-items" hidden><?php foreach ($gallery as $image): ?><li data-lightbox-item="<?= $lightboxIndex++ ?>" data-src="<?= bl_escape($image['src']) ?>" data-alt="<?= bl_escape($image['alt']) ?>" data-caption=""></li><?php endforeach; ?></ul><?php endif; ?></div>
  <div class="bl-product-intro"><p class="bl-eyebrow"><?= $copy('hero_eyebrow') ?></p><h1><?= bl_escape($product['model']) ?><span><?= bl_escape($nameLine) ?></span></h1><?php if ($modelParts = bl_model_parts($product['model'])): ?><p class="bl-model-decode"><?php foreach ($modelParts as [$code, $meaning]): ?><span><b><?= bl_escape($code) ?></b><?= bl_escape($meaning) ?></span><?php endforeach; ?><a href="<?= bl_escape(bl_url('/products/skid-steer-loaders/#model-names')) ?>"><?= $copy('hero_model_names') ?></a></p><?php endif; ?><?php if ($customExcerpt): ?><p class="bl-product-excerpt"><?= bl_escape($customExcerpt) ?></p><?php endif; ?><?php if ($keySpecs): ?><dl class="bl-product-key-specs"><?php foreach ($keySpecs as $label => $metric): ?><div><dt><?= $label ?></dt><dd><?= bl_escape($metric) ?></dd></div><?php endforeach; ?></dl><?php endif; ?><div class="bl-product-actions"><a class="bl-button bl-button-blue" href="#enquiry"><?= $copy('hero_quote') ?> <?= bl_icon('arrow-down') ?></a><a class="bl-product-wa" href="<?= bl_escape(bl_company('sales_whatsapp_url')) ?>?text=<?= rawurlencode('Hello BOB-LIFT, I am interested in the ' . $product['name'] . ' (' . $product['model'] . ').') ?>" target="_blank" rel="noopener" aria-label="WhatsApp <?= bl_escape(bl_company('sales_whatsapp_label')) ?>"><svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2Zm0 18.2a8.2 8.2 0 0 1-4.2-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2Zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.5.1a6.7 6.7 0 0 1-3.3-2.9c-.3-.4.2-.4.7-1.3.1-.2 0-.3 0-.5l-.8-1.8c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.7.3 3 3 0 0 0-.9 2.2 5.2 5.2 0 0 0 1.1 2.7 11.9 11.9 0 0 0 4.5 4 5.2 5.2 0 0 0 3.2.7 2.7 2.7 0 0 0 1.8-1.3 2.2 2.2 0 0 0 .2-1.3c-.1-.1-.3-.2-.5-.3Z"/></svg></a><a class="bl-text-link" href="#specifications"><?= $copy('hero_details') ?> <?= bl_icon('arrow-down') ?></a></div><p class="bl-product-direct"><span><?= $copy('hero_direct') ?></span><a href="<?= bl_escape(bl_company('sales_whatsapp_url')) ?>?text=<?= rawurlencode('Hello BOB-LIFT, I am interested in the ' . $product['name'] . ' (' . $product['model'] . ').') ?>" target="_blank" rel="noopener">WhatsApp <?= bl_escape(bl_company('sales_whatsapp_label')) ?></a><a href="<?= bl_escape(bl_mailto(bl_company('email'))) ?>?subject=<?= rawurlencode('Enquiry: ' . $product['name']) ?>"><?= bl_escape(bl_company('email')) ?></a></p><ul class="bl-product-terms" aria-label="Buying terms"><li><b><?= bl_escape($terms['warranty']['value'] . "\u{2011}" . rtrim($terms['warranty']['unit'], 's')) /* a non-breaking hyphen keeps "12‑month" on one line */ ?></b> <?= $copy('hero_warranty') ?></li><li><?= $copy('hero_ships') ?> <b><?= bl_escape($terms['lead']['value']) ?></b> <?= bl_escape($terms['lead']['unit']) ?></li><li><?= $copy('hero_order') ?> <b><?= bl_escape($terms['moq']['value'] . ' ' . $terms['moq']['unit']) ?></b></li><li><a href="#buying"><?= $copy('hero_buying') ?> <?= bl_icon('arrow-down') ?></a></li><?php if ($productCatalogue = bl_family_catalogue($product['category'])): ?><li><a href="<?= bl_escape($productCatalogue['url']) ?>" target="_blank" rel="noopener"><?= $copy('hero_catalogue') ?> <small><?= bl_escape($productCatalogue['kind']) ?></small> <?= bl_icon('arrow-down') ?></a></li><?php endif; ?></ul><p class="bl-source-note"><?= $copy('hero_availability') ?></p></div>
</section>
