    <article><h3><?= $copy('shipping_label') ?></h3><?php if ($loading): ?><dl class="bl-product-loading bl-product-figure"><div><dt>20GP container</dt><dd><?= (int) $loading[0] ?> <small>machine<?= $loading[0] === 1 ? '' : 's' ?></small></dd></div><div><dt>40HQ container</dt><dd><?= (int) $loading[1] ?> <small>machine<?= $loading[1] === 1 ? '' : 's' ?></small></dd></div></dl><?php endif; ?><p><?= $copy('shipping_intro', ['loading_note' => $loading ? '. ' . bl_family_copy_value($copyPage, 'product.copy.shipping_loading', ['model' => $product['model'], 'name' => $product['name']] + $leadVars) : '']) ?></p><a class="bl-text-link" href="<?= bl_escape(bl_url('/support/#containers')) ?>"><?= $copy('shipping_link') ?> <?= bl_icon('arrow-up-right') ?></a></article>
    <article><h3><?= $copy('warranty_label') ?></h3><p class="bl-product-big bl-product-figure"><?= bl_escape($terms['warranty']['value']) ?> <small><?= bl_escape($terms['warranty']['unit']) ?></small></p><p><?= $copy('warranty_scope') ?></p><a class="bl-text-link" href="<?= bl_escape(bl_url('/support/#after-delivery')) ?>"><?= $copy('warranty_link') ?> <?= bl_icon('arrow-up-right') ?></a></article>
    <article><h3><?= $copy('documents_label') ?></h3><ul class="bl-product-docs"><?php if (!bl_downloads_extended()): ?><li><a href="<?= bl_escape(bl_catalogue()['url']) ?>" target="_blank" rel="noopener"><?= bl_icon('arrow-down') ?><span><?= $copy('documents_catalogue') ?> <small>PDF<?= bl_catalogue()['size'] ? ' · ' . bl_escape(bl_catalogue()['size']) : '' ?></small></span></a></li><?php else: foreach (bl_downloads_for($product) as $document): ?><li><a href="<?= bl_escape($document['url']) ?>" target="_blank" rel="noopener"><?= bl_icon('arrow-down') ?><span><?= $document['id'] === 'catalogue' && bl_downloads_catalogue_row()['title'] === '' ? $copy('documents_catalogue') : bl_escape($document['title']) ?> <small><?= bl_escape($document['kind']) ?></small></span></a></li><?php endforeach; endif; ?><?php if ($product['specs']): ?><li><button type="button" data-print-sheet hidden><?= bl_icon('printer') ?><span><?= $copy('documents_sheet') ?> <small><?= $copy('documents_pdf') ?></small></span></button></li><?php endif; ?></ul><a class="bl-text-link" href="<?= bl_escape(bl_url('/support/#downloads')) ?>"><?= $copy('documents_link') ?> <?= bl_icon('arrow-up-right') ?></a></article>
  </div>
</section>
<?php if ($faq): ?>
<section class="bl-product-faq bl-shell" id="questions" aria-labelledby="questions-title">
  <div class="bl-product-section-head"><div><h2 class="bl-eyebrow" id="questions-title"><?= $copy('faq_label') ?></h2><p class="bl-product-display"><?= $copy('faq_title') ?></p></div><div><p><?= $copy('faq_intro') ?></p><a class="bl-text-link" href="<?= bl_escape(bl_url('/support/#faq')) ?>"><?= $copy('faq_link') ?> <?= bl_icon('arrow-up-right') ?></a></div></div>
  <div class="bl-product-faq-list"><?php foreach ($faq as $i => $item): ?><details<?= $i === 0 ? ' open' : '' ?>><summary><h3><?= bl_escape($item['q']) ?></h3></summary><div><p><?= bl_escape($item['a']) ?></p><?php if (!empty($item['link'])): ?><a class="bl-text-link" href="<?= bl_escape($item['link'][1]) ?>"><?= bl_escape($item['link'][0]) ?> <?= bl_icon('arrow-up-right') ?></a><?php endif; ?></div></details><?php endforeach; ?></div>
</section>
<?php endif; ?>
<section class="bl-product-enquiry" id="enquiry" aria-labelledby="enquiry-title">
  <div class="bl-shell bl-product-enquiry-inner">
    <div class="bl-product-enquiry-aside"><h2 class="bl-eyebrow" id="enquiry-title"><?= $copy('enquiry_label') ?></h2><p class="bl-product-display"><?= $copy('enquiry_title') ?></p><p><?= $copy('enquiry_intro') ?></p><ul class="bl-product-enquiry-direct"><li><span>WhatsApp</span><a href="<?= bl_escape(bl_company('sales_whatsapp_url')) ?>?text=<?= rawurlencode('Hello BOB-LIFT, I am interested in the ' . $product['name'] . ' (' . $product['model'] . ').') ?>" target="_blank" rel="noopener"><?= bl_escape(bl_company('sales_whatsapp_label')) ?></a></li><li><span>Email</span><a href="<?= bl_escape(bl_mailto(bl_company('email'))) ?>?subject=<?= rawurlencode('Enquiry: ' . $product['name']) ?>"><?= bl_escape(bl_company('email')) ?></a></li></ul><?php if ($product['image']): // beside the taller form: the machine and its figures fill what is left of the column, and give way when little is left ?><figure class="bl-product-enquiry-model"><div><?php if ($keySpecs): ?><dl><?php foreach ($keySpecs as $label => $metric): ?><div><dt><?= $label ?></dt><dd><?= bl_escape($metric) ?></dd></div><?php endforeach; ?></dl><?php endif; ?><span><img src="<?= bl_escape($product['image']) ?>" alt="" width="800" height="600" loading="lazy"></span></div></figure><?php endif; ?></div>
    <div class="bl-product-enquiry-form"><?php $selectedRecord = $product; $selectedFamily = $isLoader ? 'loader' : 'dumper'; $prefillMessage = bl_family_copy_value($copyPage, 'product.copy.enquiry_message', ['model' => $product['model'], 'name' => $product['name']]); require __DIR__ . '/../partials/inquiry-form.php'; ?></div>
